from itertools import compress


def primes_below(n: int) -> list[int]:
    """Return every prime p < n, in increasing order. See README.md."""
    if n <= 2:
        return []
    sieve = bytearray([1]) * n
    sieve[0] = 0
    sieve[1] = 0
    i = 2
    while i * i < n:
        if sieve[i]:
            start = i * i
            sieve[start::i] = bytes(len(range(start, n, i)))
        i += 1
    return list(compress(range(n), sieve))

